const payload = $json.body ?? $json;
const required = ['campaign_id','utm_source','utm_medium','utm_campaign','landing_page','owner','start_date'];
const errors = [];
const normalized = { ...payload };
for (const key of required) {
  if (normalized[key] === undefined || normalized[key] === null || String(normalized[key]).trim() === '') errors.push(`Missing required field: ${key}`);
}
const token = value => String(value ?? '').trim().toLowerCase().replace(/[\s-]+/g, '_').replace(/[^a-z0-9_]+/g, '').replace(/^_+|_+$/g, '');
normalized.utm_source = token(normalized.utm_source);
normalized.utm_medium = token(normalized.utm_medium);
normalized.utm_campaign = token(normalized.utm_campaign);
const allowedSources = ['google','meta','tiktok','linkedin','email','affiliate','organic'];
if (normalized.utm_source && !allowedSources.includes(normalized.utm_source)) errors.push(`Unrecognized utm_source: ${normalized.utm_source}`);
if (normalized.utm_campaign && !/^[a-z0-9]+(?:_[a-z0-9]+)*$/.test(normalized.utm_campaign)) errors.push('utm_campaign must use lowercase letters, numbers, and underscores');
if (normalized.landing_page && !String(normalized.landing_page).startsWith('https://')) errors.push('landing_page must use HTTPS');
if (normalized.start_date && !/^\d{4}-\d{2}-\d{2}$/.test(String(normalized.start_date))) errors.push('start_date must use YYYY-MM-DD');
return [{ json: { valid: errors.length === 0, normalized, errors, action: 'review_only', message: errors.length ? 'Review required; no campaign changes were published.' : 'Checks passed; campaign metadata is ready for human review.' } }];
